import Decimal from "decimal.js";

export interface CartLine {
  sku: string;
  quantity: number;
  unitPrice: string;
  oversized?: boolean;
}

export function lineTotal(line: CartLine): Decimal {
  return new Decimal(line.unitPrice).times(line.quantity);
}

export function subtotal(lines: CartLine[]): Decimal {
  return lines.reduce((sum, line) => sum.plus(lineTotal(line)), new Decimal(0));
}

