import Decimal from "decimal.js";

export interface Discount {
  code: string;
  kind: "percent" | "amount";
  value: string;
  stackable: boolean;
}

export function applyDiscounts(base: Decimal, discounts: Discount[]): Decimal {
  const ordered = [...discounts].sort((a, b) => Number(b.stackable) - Number(a.stackable));
  let running = base;
  for (const discount of ordered) {
    running = discount.kind === "percent"
      ? running.times(new Decimal(1).minus(new Decimal(discount.value).dividedBy(100)))
      : running.minus(discount.value);
    if (!discount.stackable) break;
  }
  return Decimal.max(running, 0);
}

