export interface ChargeRequest {
  amountMinor: number;
  currency: string;
  lines: Array<{ sku: string; amountMinor: number }>;
}

export interface ChargeResponse {
  id: string;
  status: "succeeded" | "requires_action" | "failed";
}

const BASE_URL = process.env.PROVIDER_BASE_URL ?? "https://api.payments.example";

export async function createCharge(charge: ChargeRequest): Promise<ChargeResponse> {
  if (process.env.PROVIDER_MODE === "replay") {
    const { replayCharge } = await import("./replay.js");
    return replayCharge(charge);
  }
  const response = await fetch(BASE_URL + "/v1/charges", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(charge),
  });
  return (await response.json()) as ChargeResponse;
}

