import Decimal from "decimal.js";

export interface CartLine {
  sku: string;
  quantity: number;
  unitPrice: string;
  oversized?: boolean;
}

const OVERSIZED_HANDLING = new Decimal("14.50");

export function lineTotal(line: CartLine): Decimal {
  return new Decimal(line.unitPrice).times(line.quantity);
}

export function subtotal(lines: CartLine[]): Decimal {
  return lines.reduce((sum, line) => sum.plus(lineTotal(line)), new Decimal(0));
}

/** Handling is its own line so the provider sees a positive charge, not an adjustment. */
export function handlingLine(lines: CartLine[]): CartLine | null {
  if (!lines.some((line) => line.oversized)) return null;
  return { sku: "HANDLING-OVERSIZE", quantity: 1, unitPrice: OVERSIZED_HANDLING.toFixed(2) };
}
